use gfc::gfc::GFC;

// All expected values below were generated by compiling and running the
// original C source from c_src/src/gfc.c with a small driver program.

#[test]
fn test_encrypt_range10_rounds6_seed42() {
    let g = GFC::new(10, 6, 42);
    let expected = [1u64, 2, 9, 4, 7, 6, 5, 8, 0, 3];
    for (i, &exp) in expected.iter().enumerate() {
        assert_eq!(g.encrypt(i as u64), exp, "encrypt({}) range=10 r=6 s=42", i);
    }
}

#[test]
fn test_decrypt_range10_rounds6_seed42() {
    // decrypt is the inverse of the encrypt mapping above.
    let g = GFC::new(10, 6, 42);
    // encrypt: 0->1, 1->2, 2->9, 3->4, 4->7, 5->6, 6->5, 7->8, 8->0, 9->3
    // so decrypt: 1->0, 2->1, 9->2, 4->3, 7->4, 6->5, 5->6, 8->7, 0->8, 3->9
    let cases = [
        (1u64, 0u64),
        (2, 1),
        (9, 2),
        (4, 3),
        (7, 4),
        (6, 5),
        (5, 6),
        (8, 7),
        (0, 8),
        (3, 9),
    ];
    for &(c, m) in cases.iter() {
        assert_eq!(g.decrypt(c), m, "decrypt({}) range=10 r=6 s=42", c);
    }
}

