#[test]
fn test_encrypt_range100_rounds6_seed42_is_permutation() {
    let g = GFC::new(100, 6, 42);
    let mut seen = [false; 100];
    for i in 0..100u64 {
        let e = g.encrypt(i);
        assert!(e < 100, "encrypt({}) = {} out of range", i, e);
        assert!(!seen[e as usize], "duplicate output {}", e);
        seen[e as usize] = true;
    }
    for (i, &b) in seen.iter().enumerate() {
        assert!(b, "value {} not produced", i);
    }
}

#[test]
fn test_encrypt_decrypt_roundtrip_range100() {
    let g = GFC::new(100, 6, 42);
    for i in 0..100u64 {
        let e = g.encrypt(i);
        let d = g.decrypt(e);
        assert_eq!(d, i, "decrypt(encrypt({})) = {}", i, d);
    }
}

#[test]
fn test_encrypt_decrypt_roundtrip_range10_various_rounds() {
    for &rounds in &[1u64, 2, 3, 4, 5, 6, 7, 8, 10] {
        let g = GFC::new(10, rounds, 42);
        for i in 0..10u64 {
            let e = g.encrypt(i);
            let d = g.decrypt(e);
            assert_eq!(d, i, "rounds={}, decrypt(encrypt({})) = {}", rounds, i, d);
            assert!(e < 10, "rounds={}, encrypt({}) = {} out of range", rounds, i, e);
        }
    }
}

#[test]
fn test_encrypt_range_one() {
    // Range = 1 — only value is 0, must map to 0.
    let g = GFC::new(1, 1, 42);
    assert_eq!(g.encrypt(0), 0);
    assert_eq!(g.decrypt(0), 0);
}

#[test]
fn test_encrypt_rounds0_is_identity() {
    // With 0 rounds, fe(m) returns m unchanged because the loop never runs
    // and the final formula reduces to a*0 + (m/a) ... wait, let's check what
    // C produces:
    //   L = m % a, R = m / a, no loop iterations
    //   r is even (0), so return a*R + L = a*(m/a) + (m%a) = m
    let g = GFC::new(100, 0, 42);
    for i in 0..100u64 {
        assert_eq!(g.encrypt(i), i, "rounds=0 encrypt({}) should be identity", i);
        assert_eq!(g.decrypt(i), i, "rounds=0 decrypt({}) should be identity", i);
    }
}

