#[test]
fn test_encrypt_range4_rounds6_seed42() {
    // Full mapping for range=4 (smallest non-trivial perfect square > 1).
    let expected = [3u64, 2, 1, 0];
    let g = GFC::new(4, 6, 42);
    for i in 0..4u64 {
        assert_eq!(g.encrypt(i), expected[i as usize], "encrypt({}) range=4", i);
    }
    // Round-trip check.
    for i in 0..4u64 {
        assert_eq!(g.decrypt(g.encrypt(i)), i);
    }
}

