#[test]
fn test_full_bijection_range_500() {
    // Ensure bijection over a larger non-perfect-square range.
    let range = 500u64;
    let g = GFC::new(range, 6, 42);
    let mut seen = vec![false; range as usize];
    for i in 0..range {
        let e = g.encrypt(i);
        assert!(e < range, "encrypt({}) = {} out of range", i, e);
        assert!(!seen[e as usize], "duplicate output {}", e);
        seen[e as usize] = true;
        // round-trip
        let d = g.decrypt(e);
        assert_eq!(d, i, "decrypt(encrypt({})) = {}", i, d);
    }
    for (i, &b) in seen.iter().enumerate() {
        assert!(b, "value {} not produced", i);
    }
}

#[test]
fn test_full_bijection_range_256_perfect_square() {
    // range=256 is a perfect square (a=b=16, a*b=256=range).
    let range = 256u64;
    let g = GFC::new(range, 6, 42);
    let mut seen = vec![false; range as usize];
    for i in 0..range {
        let e = g.encrypt(i);
        assert!(e < range);
        assert!(!seen[e as usize]);
        seen[e as usize] = true;
        assert_eq!(g.decrypt(e), i);
    }
    for &b in seen.iter() {
        assert!(b);
    }
    // Also assert specific values.
    assert_eq!(g.encrypt(0), 85);
    assert_eq!(g.encrypt(100), 155);
    assert_eq!(g.encrypt(255), 192);
}

